from solution import is_Sum_Of_Powers_Of_Two


def test_issue_example_ten():
    """Example assert is_Sum_Of_Powers_Of_Two(10) == True."""
    assert is_Sum_Of_Powers_Of_Two(10) == True  # 10 = 8 + 2


def test_issue_smallest_power_two():
    """Power of 2 can be represented as sum of non-zero powers of 2."""
    assert is_Sum_Of_Powers_Of_Two(2) == True  # 2 = 2^1


def test_issue_power_of_two_eight():
    """Power of 2 can be represented as sum of non-zero powers of 2."""
    assert is_Sum_Of_Powers_Of_Two(8) == True  # 8 = 2^3


def test_issue_power_of_two_sixteen():
    """Power of 2 can be represented as sum of non-zero powers of 2."""
    assert is_Sum_Of_Powers_Of_Two(16) == True  # 16 = 2^4


def test_issue_sum_six():
    """Number representable as sum of non-zero powers of 2 returns True."""
    assert is_Sum_Of_Powers_Of_Two(6) == True  # 6 = 4 + 2


def test_issue_sum_twelve():
    """Number representable as sum of non-zero powers of 2 returns True."""
    assert is_Sum_Of_Powers_Of_Two(12) == True  # 12 = 8 + 4


def test_issue_sum_forty():
    """Number representable as sum of non-zero powers of 2 returns True."""
    assert is_Sum_Of_Powers_Of_Two(40) == True  # 40 = 32 + 8


def test_issue_large_power_of_two():
    """Power of 2 can be represented as sum of non-zero powers of 2."""
    assert is_Sum_Of_Powers_Of_Two(1024) == True  # 1024 = 2^10


def test_issue_zero_is_false():
    """Zero cannot be a sum of non-zero powers of 2."""
    assert is_Sum_Of_Powers_Of_Two(0) == False  # 0 < 2, no sum of terms >= 2 equals 0


def test_issue_negative_is_false():
    """Negative number cannot be a sum of non-zero powers of 2."""
    assert is_Sum_Of_Powers_Of_Two(-4) == False  # -4 < 0 < sum of positive powers


def test_contract_exact_bool_on_true():
    """Check whether representable or not must return boolean True."""
    assert is_Sum_Of_Powers_Of_Two(10) is True  # 10 = 8 + 2


def test_contract_exact_bool_on_false():
    """Check whether representable or not must return boolean False."""
    assert is_Sum_Of_Powers_Of_Two(0) is False  # 0 < 2, no sum of terms >= 2 equals 0
